import styled from '@emotion/styled';
import * as RadioGroupPrimitive from '@radix-ui/react-radio-group';
import { AlertOctagon } from 'components/icon';
import { theme } from 'theme';
import { transientShouldForwardProp } from 'utils/emotion';

interface StyledGroupProps {
  $error?: boolean;
}

interface StyledIndicatorProps {
  $disabled?: boolean;
}

interface StyledLabelProps {
  $disabled?: boolean;
}

export const StyledErrorMessage = styled('div')({
  alignItems: 'center',
  color: theme.colors.semanticErrorText,
  display: 'flex',
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['1'],
  lineHeight: theme.fonts.lineHeights['4'],
  marginTop: theme.spacing['2'],
});

export const StyledErrorIcon = styled(AlertOctagon)({
  color: theme.colors.semanticErrorText,
  marginLeft: 0,
  marginRight: theme.spacing['1'],
});

export const StyledGroup = styled(RadioGroupPrimitive.Root, {
  shouldForwardProp: transientShouldForwardProp,
})<StyledGroupProps>(({ $error }) => ({
  ...($error
    ? {
        '& > div > button:not([disabled])': {
          border: `0.0625rem solid ${theme.colors.semanticErrorText}`,
          '&:hover:not([disabled])': {
            outline: `${theme.colors.semanticErrorText} solid 0.125rem`,
            outlineOffset: '-0.125rem',
          },
          '&:focus': {
            outline: `${theme.colors.semanticErrorText} solid 0.125rem`,
            outlineOffset: '-0.125rem',
          },
          '&[aria-checked="true"]': {
            border: `0.0625rem solid ${theme.colors.semanticErrorText}`,
          },
          '& > span::after': {
            backgroundColor: theme.colors.semanticErrorText,
          },
        },
      }
    : {}),
}));

export const StyledContainer = styled('div')({
  alignItems: 'center',
  display: 'flex',
  margin: `${theme.spacing['4']} 0`,
});

export const StyledRadioItem = styled(RadioGroupPrimitive.Item)({
  all: 'unset',
  border: `0.0625rem solid ${theme.colors.interfaceLabelSecondary}`,
  borderRadius: '100%',
  boxSizing: 'border-box',
  cursor: 'pointer',
  height: '1.25rem',
  width: '1.25rem',
  '&:hover:not([disabled])': {
    outline: `${theme.colors.interfaceLabelPrimary} solid 0.125rem`,
    outlineOffset: '-0.125rem',
  },
  '&:focus': {
    outline: `${theme.colors.interfaceLabelPrimary} solid 0.125rem`,
    outlineOffset: '-0.125rem',
  },
  '&[aria-checked="true"]': {
    border: `0.0625rem solid ${theme.colors.interfaceLabelPrimary}`,
  },
  '&:disabled': {
    border: `0.0625rem solid ${theme.colors.interfaceLabelDisabled}`,
    cursor: 'auto',
  },
});

export const StyledIndicator = styled(RadioGroupPrimitive.Indicator, {
  shouldForwardProp: transientShouldForwardProp,
})<StyledIndicatorProps>(({ $disabled }) => ({
  alignItems: 'center',
  display: 'flex',
  height: '100%',
  justifyContent: 'center',
  position: 'relative',
  width: '100%',
  '&::after': {
    backgroundColor: $disabled
      ? theme.colors.interfaceLabelSecondary
      : theme.colors.interfaceLabelPrimary,
    borderRadius: '50%',
    content: '""',
    display: 'block',
    height: '0.5rem',
    width: '0.5rem',
  },
}));

export const StyledLabel = styled('label')<StyledLabelProps>(
  ({ $disabled }) => ({
    color: $disabled
      ? theme.colors.interfaceLabelDisabled
      : theme.colors.interfaceLabelPrimary,
    cursor: $disabled ? 'default' : 'pointer',
    fontFamily: theme.fonts.paragraph,
    fontSize: theme.fonts.fontSizes['3'],
    fontWeight: theme.fonts.fontWeights.normal,
    lineHeight: theme.fonts.lineHeights['6'],
    paddingLeft: theme.spacing['4'],
    ...(!$disabled
      ? {
          '&:hover': {
            fontWeight: theme.fonts.fontWeights.medium,
          },
        }
      : {}),
  }),
);
